H.background();
const ax = P.ax, ay = P.ay, bx = P.bx, by = 0;
const s = P.bx;
const op = Math.round(P.op);
let rx, ry, label, opName;
if (op <= 0) { rx = ax + bx; ry = ay + by; label = "a + b"; opName = "addition"; }
else if (op === 1) { rx = ax - bx; ry = ay - by; label = "a - b"; opName = "subtraction"; }
else { rx = s * ax; ry = s * ay; label = s.toFixed(1) + "·a"; opName = "scalar multiple"; }
// Adaptive view: make sure every drawn vector tip fits on-screen at all settings.
const xsAll = [ax, bx, rx, ax + bx, ax - bx, 0];
const ysAll = [ay, by, ry, ay + by, ay - by, 0];
let mx = 1, my = 1;
for (let i = 0; i < xsAll.length; i++) mx = Math.max(mx, Math.abs(xsAll[i]));
for (let i = 0; i < ysAll.length; i++) my = Math.max(my, Math.abs(ysAll[i]));
const xR = mx * 1.25, yR = my * 1.25;
const view = H.plot2d({ xMin: -xR, xMax: xR, yMin: -yR, yMax: yR });
view.grid(); view.axes();
view.arrow(0, 0, ax, ay, { color: H.colors.good, width: 3 });
